        function saveGame() {
            try {
                localStorage.setItem(STORAGE_KEY, JSON.stringify(gameState));
            } catch(e) { console.error("Could not save to localStorage", e); }
        }

        function loadGame() {
            try {
                const saved = localStorage.getItem(STORAGE_KEY);
                if (saved) {
                    gameState = JSON.parse(saved);
                    return true;
                }
            } catch(e) { console.error("Could not load from localStorage", e); }
            return false;
        }

        function confirmResetGame() {
            playSynthSound('click');
            document.getElementById('modal-reset').classList.remove('hidden');
        }

        function closeResetModal() {
            playSynthSound('click');
            document.getElementById('modal-reset').classList.add('hidden');
        }

        function executeResetGame() {
            playSynthSound('click');
            localStorage.removeItem(STORAGE_KEY);
            location.reload();
        }

        /* Timer Logic */
        function startTimer() {
            if (timerInterval) clearInterval(timerInterval);
            gameState.timerActive = true;
            timerInterval = setInterval(() => {
                if (gameState.timerActive) {
                    gameState.timeSeconds++;
                    updateTimerUI();
                    if (gameState.timeSeconds % 10 === 0) saveGame();
                }
            }, 1000);
        }

        function updateTimerUI() {
            const mins = Math.floor(gameState.timeSeconds / 60).toString().padStart(2, '0');
            const secs = (gameState.timeSeconds % 60).toString().padStart(2, '0');
            const formatted = `${mins}:${secs}`;
            document.getElementById('header-timer').innerText = formatted;
            document.getElementById('report-time').innerText = formatted;
        }

