        function convertPyCondToJs(cond) {
            if (!cond) return 'true';
            return cond
                .replace(/\band\b/g, '&&')
                .replace(/\bor\b/g, '||')
                .replace(/\bnot\b/g, '!')
                .replace(/\bTrue\b/g, 'true')
                .replace(/\bFalse\b/g, 'false');
        }

        function parsePythonToJs(code) {
            let lines = code.split('\n');
            let jsLines = [];
            let indentStack = [];

            for (let rawLine of lines) {
                let commentIdx = rawLine.indexOf('#');
                let lineWithoutComment = commentIdx !== -1 ? rawLine.substring(0, commentIdx) : rawLine;
                if (!lineWithoutComment.trim()) continue;

                if (lineWithoutComment.includes('input(')) continue;

                let indentMatch = rawLine.match(/^\s*/);
                let indent = indentMatch ? indentMatch[0].length : 0;
                let trimmed = lineWithoutComment.trim();

                while (indentStack.length > 0 && indent <= indentStack[indentStack.length - 1]) {
                    indentStack.pop();
                    jsLines.push('}');
                }

                let isIf = /^if\s+.*:$/.test(trimmed);
                let isElif = /^elif\s+.*:$/.test(trimmed);
                let isElse = /^else\s*:$/.test(trimmed);

                if (isIf) {
                    let cond = convertPyCondToJs(trimmed.replace(/^if\s+/, '').replace(/:$/, ''));
                    jsLines.push(`if (${cond}) {`);
                    indentStack.push(indent);
                } else if (isElif) {
                    let cond = convertPyCondToJs(trimmed.replace(/^elif\s+/, '').replace(/:$/, ''));
                    jsLines.push(`else if (${cond}) {`);
                    indentStack.push(indent);
                } else if (isElse) {
                    jsLines.push(`else {`);
                    indentStack.push(indent);
                } else {
                    let jsLine = trimmed
                        .replace(/print\((.*)\)/g, 'print($1)')
                        .replace(/\bTrue\b/g, 'true')
                        .replace(/\bFalse\b/g, 'false');
                    if (!jsLine.endsWith(';') && !jsLine.endsWith('{') && !jsLine.endsWith('}')) {
                        jsLine += ';';
                    }
                    jsLines.push(jsLine);
                }
            }

            while (indentStack.length > 0) {
                indentStack.pop();
                jsLines.push('}');
            }

            return jsLines.join('\n');
        }

        /* Simulation helper for Challenge 3.3 */
        function simulatePythonClassifier(code, scoreVal) {
            try {
                function str(v) { return String(v); }
                function int(v) { return parseInt(v, 10) || 0; }
                function float(v) { return parseFloat(v) || 0; }
                function round(v, p = 0) { return Number(Math.round(v + "e" + p) + "e-" + p); }

                let cleanedCode = code.replace(/^\s*pontuacao\s*=.*$/gm, '# pontuacao set by test runner');
                let parsedJs = parsePythonToJs(cleanedCode);
                let fullJs = `
                    let output = [];
                    function print(...args) { output.push(args.map(String).join(' ')); }
                    let pontuacao = ${scoreVal};
                    ${parsedJs}
                    return output.join("\\n");
                `;

                const f = new Function('str', 'int', 'float', 'round', fullJs);
                return f(str, int, float, round);
            } catch(e) {
                return "ERRO DE EXECUÇÃO: " + e.message;
            }
        }

        /* Simulation helper for Secret Final Protocol */
        function simulateSimpleSecret(code, acertosVal) {
            try {
                function str(v) { return String(v); }
                function int(v) { return parseInt(v, 10) || 0; }
                function float(v) { return parseFloat(v) || 0; }

                let cleanedCode = code.replace(/^\s*acertos\s*=.*$/gm, '# acertos injected');
                let parsedJs = parsePythonToJs(cleanedCode);
                let fullJs = `
                    let output = [];
                    function print(...args) { output.push(args.map(String).join(' ')); }
                    let acertos = ${acertosVal};
                    ${parsedJs}
                    return output.join("\\n");
                `;

                const f = new Function('str', 'int', 'float', fullJs);
                return f(str, int, float);
            } catch(e) {
                return "ERRO DE EXECUÇÃO: " + e.message;
            }
        }

